use std::{collections::{BTreeMap,BTreeSet},fs};use serde_json::{json,Value};use sha2::{Digest,Sha256};use zopro_bn254::Fr;
mod model;mod split;mod geometry;type Word=[u64;4];
fn groups(words:&[Word])->Option<(Vec<Word>,Vec<usize>)>{let n=words.len();if n<256{return None}let sample=n.min(2048);let stride=n.div_ceil(sample);let seen=words.iter().step_by(stride).take(sample).collect::<BTreeSet<_>>();let observed=n.div_ceil(stride).min(sample);if seen.len()*200>observed*199{return None}let percent=if(32768..65536).contains(&n){95}else{80};let zeros=words.iter().step_by(stride).take(sample).filter(|s|**s==[0;4]).count();let nonzero=observed-zeros;if seen.len()-usize::from(zeros!=0)==nonzero&&nonzero*100>observed*percent{return None}let mut map=BTreeMap::new();let mut values=vec![];let mut classes=vec![usize::MAX;n];for(i,&v)in words.iter().enumerate(){if v==[0;4]{continue}let class=*map.entry(v).or_insert_with(||{values.push(v);values.len()-1});classes[i]=class;}if values.len()*100>n*percent{None}else{Some((values,classes))}}
fn token(seed:&mut u64)->Fr{let mut b=[0;32];for c in b.chunks_mut(8){*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;c.copy_from_slice(&seed.to_le_bytes());}Fr::from_le_bytes_mod_order(&b)}
fn aggregate(rows:&[Value],policy:&str)->Value{let mut sums=BTreeMap::<String,usize>::new();for row in rows.iter().filter(|r|r["policy"]==policy&&r["route"]=="ordinary"){for(k,v)in row["counts"].as_object().unwrap(){if let Some(n)=v.as_u64(){let s=sums.entry(k.clone()).or_default();if k=="max_batch"||k=="max_queue"{*s=(*s).max(n as usize)}else{*s+=n as usize}}}}json!(sums)}
fn census(words:&[Word],mapping:Option<&[usize]>,original_n:usize)->Value{let short=words.iter().map(|&v|split::phi_split(v)).collect::<Vec<_>>();let lambda=split::phi_lambda();for(s,w)in short.iter().zip(words){geometry::check(s);assert_eq!(geometry::signed_fr(geometry::scalar(s,false))+lambda*geometry::signed_fr(geometry::scalar(s,true)),Fr::from_le_bytes_mod_order(&w.into_iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()));for j in 0..11{for high in[false,true]{assert_eq!(geometry::digit(s,high,geometry::original()[j]),split::digit_of(s,high,j,12));}}}
 let mut first=None;for tag in 0..2{let mut seed=0x62616c616e636564u64^tag;let original=(0..original_n).map(|_|token(&mut seed)).collect::<Vec<_>>();let tokens=if let Some(classes)=mapping{let mut t=vec![Fr::ZERO;words.len()];for(&c,v)in classes.iter().zip(&original){if c!=usize::MAX{t[c]+=*v;}}t}else{original.clone()};let target=words.iter().zip(&tokens).map(|(s,p)|Fr::from_le_bytes_mod_order(&s.into_iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>())* *p).fold(Fr::ZERO,|a,b|a+b);let mut rows=vec![];
 for (policy,spans) in[("original",geometry::original()),("balanced",geometry::balanced())]{let mut weighted=Fr::ZERO;let chunk=words.len().div_ceil(2);for(w,span)in spans.iter().copied().enumerate(){let indexed=policy=="original"&&w==10;let half=if indexed{64}else{1usize<<(span.width-1)};let size=if span.width==11{152}else{200};for part in 0..2{let start=(part*chunk).min(words.len());let end=(start+chunk).min(words.len());let mut expected=vec![Fr::ZERO;half];let mut m=model::Model::new(half,size,false);let mut bins=vec![0usize;4*half];let mut bin_sums=vec![Fr::ZERO;4*half];let mut indexed_arrivals=0;
 for (component,high)in[true,false].into_iter().enumerate(){let arrivals=(start..end).filter_map(|i|{let d=geometry::digit(&short[i],high,span);if d==0{return None;}let b=d.unsigned_abs()as usize-1;assert!(b<half);expected[b]+=if d<0{-tokens[i]}else{tokens[i]};if indexed{let slot=component*2*half+b+if d<0{half}else{0};bins[slot]+=1;bin_sums[slot]+=tokens[i];indexed_arrivals+=1;}Some((b as u32|if d<0{1<<31}else{0},tokens[i]))}).collect::<Vec<_>>();if !indexed{m.feed(&arrivals);}if high{for p in &mut expected{*p*=lambda;}if !indexed{m.phi(lambda);}}}
 let buckets=if indexed{let result=(0..half).map(|i|(bin_sums[i]-bin_sums[half+i])*lambda+bin_sums[2*half+i]-bin_sums[3*half+i]).collect::<Vec<_>>();assert_eq!(result,expected);result}else{let(b,c)=m.finish();assert_eq!(b,expected);assert!(c.max_batch<=200&&c.max_queue<size);rows.push(json!({"policy":policy,"route":"ordinary","window":w,"part":part,"offset":span.start,"width":span.width,"bucket_slots":half,"counts":c.json(),"every_bucket_oracle_checked":true}));b};if indexed{rows.push(json!({"policy":policy,"route":"indexed-top","window":w,"part":part,"offset":span.start,"source_digit_width":span.width,"effective_top_bits":6,"bucket_slots":half,"arrivals":indexed_arrivals,"within_sign_tree_pairs":bins.iter().map(|n|n.saturating_sub(1)).sum::<usize>(),"nonempty_sign_bins":bins.iter().filter(|n|**n!=0).count(),"actual_arithmetic_exceptions_and_inversions_not_modeled":true,"every_bin_direct_sum_checked":true}));}let sum=buckets.iter().enumerate().map(|(i,p)|Fr::from((i+1)as u64)* *p).fold(Fr::ZERO,|a,b|a+b);weighted+=sum*Fr::from(2u64).pow(&[span.start as u64]);}}
 assert_eq!(weighted,target,"whole weighted sum{policy}");}
 if let Some(old)=&first{assert_eq!(old,&rows);}else{first=Some(rows);}}
 let rows=first.unwrap();json!({"original_B_rows":original_n,"scalar_terms":words.len(),"grouping_admitted":mapping.is_some(),"source_original_ordinary":aggregate(&rows,"original"),"balanced_all_ordinary":aggregate(&rows,"balanced"),"rows":rows,"two_independent_token_streams":true,"every_Phi_Booth_reconstruction_exact":true,"both_weighted_whole_sums_match_original_scalar_dot_product":true,"original_bucket_slots_per_part":20544,"balanced_bucket_slots_per_part":17408,"original_ordinary_jobs":20,"original_indexed_top_jobs":2,"balanced_ordinary_jobs":22,"baseline_total_inversion_cost_not_modeled":true})}
fn main(){let root="/home/ubuntu/src/zopro-perf-work/g2-queue-scan175";for shape in["1x2","2x2"]{let path=format!("{root}/inputs/{shape}.b2q");let b=fs::read(&path).unwrap();let oracle:Value=serde_json::from_slice(&fs::read(format!("{root}/oracle-fixed-runs/oracle-{shape}/stdout.log")).unwrap()).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&b)),oracle["fixture_sha256"]);let n=u64::from_le_bytes(b[8..16].try_into().unwrap())as usize;assert_eq!(b.len(),16+160*n);let words=b[16+128*n..].chunks_exact(32).map(|b|core::array::from_fn(|i|u64::from_le_bytes(b[i*8..i*8+8].try_into().unwrap()))).collect::<Vec<Word>>();let g=groups(&words);let mut row=if let Some((values,classes))=&g{census(values,Some(classes),n)}else{census(&words,None,n)};row["shape"]=json!(shape);println!("ROW {}",row);}println!("COMPLETE {}",json!({"necessary_opportunity_gate":true,"digit_and_bucket_oracles":true,"indexed_route_removed":true,"old_heap_forecast_envelope_retained":true,"metadata_requested_stack_bytes":176,"no_actual_curve_or_performance_qualification":true,"new_solver_calls":0,"SDK_requests":0,"new_independent_exports":0,"proof_ledger":23971,"production_changed":false,"performance_claim":false,"goal_achieved":false}));}
